-- Seed for scripts/test-actions-local.sh. Local fixture only; fictional data.
-- tournaments: ids c0..01 deposit, 02 plain, 03 retry, 04 undo, 05 forced failure, 06/07 concurrency, 08 other org
-- the FAIL tournament: its status update is made to error AFTER the payment insert, to prove the whole save rolls back
create function public.test_fail_status() returns trigger language plpgsql as $$
begin if new.name = 'FAIL' and new.paid_status is distinct from old.paid_status then raise exception 'forced failure'; end if; return new; end $$;
create trigger test_fail before update on public.tournaments for each row execute function public.test_fail_status();
